var i=`0093-chiftelute`;var o=`world-0093`;var t=`MD`;var a=`eastern-europe`;var s=4;var l=27;var r={en:`Chifteluțe`,ua:`Молдовські котлетки`};var g={en:`A classic dish from Moldova, featuring ground pork, yellow onion, chicken egg, garlic. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Молдова. Основні складники: свинячий фарш, жовта цибуля, куряче яйце, часник. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`ground-pork`,500,`g`],[`yellow-onion`,130,`g`],[`chicken-egg`,1,`pcs`],[`breadcrumbs`,90,`g`],[`garlic`,3,`clove`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`sunflower-oil`,50,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,16,`g`]]}];var u={slug:i,id:o,country:`MD`,region:a,servings:4,minutes:27,title:r,text:g,steps:d};export{t as country,u as default,o as id,l as minutes,a as region,s as servings,i as slug,d as steps,g as text,r as title};